import React from "react";
import { useNavigate } from "react-router-dom";
import { storage, STORAGE_KEYS } from "../utils/storage";
import "./ScoreboardPage.css";

const ScoreboardPage = () => {
  const navigate = useNavigate();
  const highScores = storage.getItem(STORAGE_KEYS.HIGH_SCORES) || [];
  const reviews = storage.getItem(STORAGE_KEYS.REVIEWS) || [];

  const handleBackToHome = () => {
    navigate("/");
  };

  return (
    <div className="scoreboard-container">
      <div className="scoreboard-header">
        <h1>Scoreboard & Reviews</h1>
        <button className="back-btn" onClick={handleBackToHome}>
          Back to Home
        </button>
      </div>

      <div className="scoreboard-content">
        {/* High Scores Section */}
        <div className="scores-section">
          <h2>🏆 Top Scores</h2>
          {highScores.length > 0 ? (
            <div className="scores-list">
              {highScores.map((score, index) => (
                <div key={index} className="score-item">
                  <div className="rank">#{index + 1}</div>
                  <div className="player-info">
                    <div className="player-name">{score.userDetails.name}</div>
                    <div className="player-school">
                      {score.userDetails.school}
                    </div>
                  </div>
                  <div className="score-value">{score.score} pts</div>
                </div>
              ))}
            </div>
          ) : (
            <p className="no-data">No scores yet. Be the first to play!</p>
          )}
        </div>

        {/* Reviews Section */}
        <div className="reviews-section">
          <h2>💬 User Reviews</h2>
          {reviews.length > 0 ? (
            <div className="reviews-list">
              {reviews.map((review, index) => (
                <div key={index} className="review-item">
                  <div className="review-header">
                    <span className="review-rating">
                      {review.rating === "good" && "😊 Good"}
                      {review.rating === "bad" && "😞 Bad"}
                      {review.rating === "excellent" && "🤩 Excellent"}
                    </span>
                    <span className="review-date">
                      {new Date(review.timestamp).toLocaleDateString()}
                    </span>
                  </div>
                  {review.text && (
                    <p className="review-text">"{review.text}"</p>
                  )}
                </div>
              ))}
            </div>
          ) : (
            <p className="no-data">
              No reviews yet. Be the first to share your thoughts!
            </p>
          )}
        </div>
      </div>
    </div>
  );
};

export default ScoreboardPage;
